function loadFormattedItems() {
  const candidates = [
    'Format Run Pipeline',
    'Format Strict Reject Message',
  ];
  const errors = [];
  for (const name of candidates) {
    try {
      const items = $(name).all();
      if (Array.isArray(items) && items.length > 0) {
        return { source: name, items };
      }
      errors.push(name + ': executed but empty');
    } catch (e) {
      errors.push(name + ': ' + String((e && e.message) || e));
    }
  }
  throw new Error(
    'HOTFIX01 Restore: no formatted items from Format Run Pipeline or Format Strict Reject Message. ' +
    errors.join(' | ')
  );
}

const loaded = loadFormattedItems();
return loaded.items.map((item) => ({
  json: {
    ...item.json,
    _restore_source: loaded.source,
  },
}));
